head.script:
scwin.screenId = "jldinf92400";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_14", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0); } }, { id: "c_when_19", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y'); } }, { id: "c_when_24", fn: function(){ return ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y'); } }, { id: "c_when_29", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y'); } }, { id: "c_when_34", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D'); } }, { id: "c_otherwise_39", fn: function(){ return (!(((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0) || ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y') || ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y') || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y') || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D'))); } }, { id: "c_when_12", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(dma_map.get("activYn")) + "* 발행기관이 비활성인 종목은 수정할 수 없습니다."; } },
        { childId: "__rb1", fn: function () { return String(dma_map.get("activTpCd")) + "* 표준코드가 비활성인 종목은 수정할 수 없습니다."; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setComma();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf92400.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf92400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
