    /* sdd-asis-lifecycle:begin setComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.num.formatNumber($('#ipt_isuAmt')[0]);
    $c.util.getComponent('txt_isuAmtTd').setLabel($c.util.getComponent('ipt_isuAmt').getValue());
    /* sdd-asis-lifecycle:end */
};


/**
