    /* sdd-asis-lifecycle:begin open_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const stdcdType = $c.util.getComponent('ipt_stdcdType').getValue();
    const stdCd = $c.util.getComponent('ipt_stdCd').getValue();
    const form = (document.JLDINF92400 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue("mod");
    fn_passwordWin(form);
    /* sdd-asis-lifecycle:end */
};


