*/
scwin.go_modify = async function () {
    /* sdd-asis-lifecycle:begin go_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF92400 || { elements: [] });
    const url = "/stdcd/stdcdModify.do?method=stdcdModify&type=12&std_cd=" + $c.util.getComponent('ipt_stdCd').getValue();
    fm.action = url;
    fm.target = "_top";
    await moveUrl(url, {});
    /* sdd-asis-lifecycle:end */
};


