    const form = (document.JLDINF92400 || { elements: [] });
    fn_stdCdDelWin(form);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.Cancel_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.Cancel_form = function () {
    /* sdd-asis-lifecycle:begin Cancel_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent)._popupWindow.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = async function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("ETN 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport14&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printOld
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printOld = async function () {
    /* sdd-asis-lifecycle:begin fn_print_old — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm("ETN 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const formName = (document.JLDINF92400 || { elements: [] });
        const std_cd = $c.util.getComponent('dma_printReq').get('stdCd');
        const rexName = "JLDINF92400";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport14&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
    }
    /* sdd-asis-lifecycle:end */
};
